/** Kind and hint of the codes `@lamina/pdf` raises itself (the WASM fills in the others). */
export const RAISED_BY_PACKAGE = {
  "builder-finished": {
    kind: "state",
    hint: "create a new builder or page: a finished one takes no more drawing, pages, fonts or settings",
  },
  "invalid-argument": {
    kind: "usage",
    hint: "pass the value the type declarations describe; the data field says what was wrong",
  },
  "nested-transaction": {
    kind: "state",
    hint: "commit or roll back the open transaction first, or use a savepoint inside it",
  },
  "no-transaction": {
    kind: "state",
    hint: "call begin first, or use transact",
  },
  "already-initialized": {
    kind: "state",
    hint: "call init and loadText with a source once, before the first load; later calls need no source",
  },
  "fetch-failed": {
    kind: "io",
    hint: "check that the URL is reachable and that the server sends the CORS headers range requests need; data.status has the HTTP status",
  },
  "not-initialized": {
    kind: "state",
    hint: "await init() once before calling anything else in @lamina/pdf",
  },
  "source-changed": {
    kind: "io",
    hint: "open the file again; the document already read parts of the old version and can't mix in the new one",
  },
  "text-module-not-loaded": {
    kind: "state",
    hint: "load the text module with init and the text option, or with loadText, before creating the builder that draws text",
  },
} as const;
